1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult =
36	  { premium: number } | { payout: number; remainingCap: number };
37	
38	export interface ScenarioResult {
39	  results: StepResult[];
40	}
41	
42	const PROCESSING_FEE = 5;
43	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
44	const BASE_PREMIUM_RATES: Record<string, number> = {
45	  sword: 100,
46	  amulet: 60,
47	  staff: 80,
48	  potion: 40,
49	  rune: 25,
50	  moonstone: 25,
51	};
52	
53	const CURSE_SURCHARGE_RATE = 0.5;
54	const HIGH_ENCHANTMENT_THRESHOLD = 5;
55	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
56	const LOYALTY_YEARS_THRESHOLD = 2;
57	const LOYALTY_DISCOUNT_RATE = 0.2;
58	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
59	const COMPONENT_BLOCK_SIZE = 3;
60	const COMPONENT_BLOCK_PREMIUM = 60;
61	
62	const INSURANCE_VALUES: Record<string, number> = {
63	  sword: 1000,
64	  amulet: 600,
65	  staff: 800,
66	  potion: 400,
67	  rune: 250,
68	  moonstone: 250,
69	};
70	
71	const DEDUCTIBLE_PER_DAMAGE = 100;
72	const CAP_MULTIPLIER = 2;
73	const HALF_REIMBURSEMENT_ENCHANTMENT = 8;
74	const HALF_REIMBURSEMENT_RATE = 0.5;
75	const FULL_REIMBURSEMENT_RATE = 1;
76	
77	const countByType = (items: Item[]): Map<string, number> =>
78	  items.reduce(
79	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
80	    new Map<string, number>(),
81	  );
82	
83	const basePremiumForGroup = (type: string, itemCount: number): number =>
84	  itemCount === COMPONENT_BLOCK_SIZE
85	    ? COMPONENT_BLOCK_PREMIUM
86	    : itemCount * BASE_PREMIUM_RATES[type];
87	
88	// The policy base premium: the sum of all item base premiums, EXCLUDING
89	// item-specific surcharges. Policy-wide modifiers are percentages of this.
90	const policyBasePremium = (items: Item[]): number =>
91	  [...countByType(items)].reduce(
92	    (sum, [type, itemCount]) => sum + basePremiumForGroup(type, itemCount),
93	    0,
94	  );
95	
96	const itemSurchargeRate = (item: Item): number =>
97	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
98	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
99	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
100	    : 0);
101	
102	const sumItemSurcharges = (items: Item[]): number =>
103	  items.reduce(
104	    (sum, item) =>
105	      sum + BASE_PREMIUM_RATES[item.type] * itemSurchargeRate(item),
106	    0,
107	  );
108	
109	// Premiums round in the MHPCO's favor, i.e. up.
110	const roundPremiumInMHPCOsFavor = (premium: number): number =>
111	  Math.ceil(premium);
112	
113	// What the office knows about the customer at the moment a quote is drawn up.
114	// Policy-wide modifiers are decided entirely by this context.
115	interface QuoteContext {
116	  customer: Customer;
117	  precedingQuoteCount: number;
118	}
119	
120	// Each policy-wide modifier is a signed percentage of the policy base premium:
121	// surcharges positive, discounts negative.
122	const policyWideModifierRates = ({
123	  customer,
124	  precedingQuoteCount,
125	}: QuoteContext): number[] => [
126	  FIRST_INSURANCE_SURCHARGE_RATE,
127	  ...(customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
128	    ? [-LOYALTY_DISCOUNT_RATE]
129	    : []),
130	  ...(precedingQuoteCount > 0 ? [-FOLLOW_UP_CONTRACT_DISCOUNT_RATE] : []),
131	];
132	
133	// Each rate is multiplied out against the base premium SEPARATELY and then
134	// summed. Summing the rates first and doing a single multiply is algebraically
135	// equal but not equal in floating point — 100 * (1 + 0.1) is 110.00000000000001
136	// — and rounding up turns that into a spurious extra gold piece.
137	const sumPolicyWideModifiers = (
138	  basePremium: number,
139	  context: QuoteContext,
140	): number =>
141	  policyWideModifierRates(context).reduce(
142	    (sum, rate) => sum + basePremium * rate,
143	    0,
144	  );
145	
146	const quote = (items: Item[], context: QuoteContext): StepResult => {
147	  const unknown = items.find(({ type }) => !(type in BASE_PREMIUM_RATES));
148	  if (unknown) {
149	    throw new Error(`Unknown item type: ${unknown.type}`);
150	  }
151	
152	  const basePremium = policyBasePremium(items);
153	
154	  return {
155	    premium: roundPremiumInMHPCOsFavor(
156	      basePremium +
157	        sumItemSurcharges(items) +
158	        sumPolicyWideModifiers(basePremium, context) +
159	        PROCESSING_FEE,
160	    ),
161	  };
162	};
163	
164	const policyInsuranceSum = (items: Item[]): number =>
165	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
166	
167	// How much of a damage the office reimburses, before the deductible.
168	//
169	// Full reimbursement is the default, which is also what the dragon-material
170	// clause grants — so that clause needs no branch of its own. The only clause
171	// that moves the rate off the default is high enchantment, and the spec makes
172	// it win outright when both apply, so testing it alone is the whole rule.
173	const reimbursementRate = (item: Item): number =>
174	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT
175	    ? HALF_REIMBURSEMENT_RATE
176	    : FULL_REIMBURSEMENT_RATE;
177	
178	// The deductible bites once per damaged item, after the rate, and never turns
179	// a payout negative — the office does not bill the customer for small damages.
180	const payoutForDamage = (damage: Damage, item: Item): number =>
181	  Math.max(0, damage.amount * reimbursementRate(item) - DEDUCTIBLE_PER_DAMAGE);
182	
183	// Each damage entry claims one distinct insured item, so a matched item is
184	// consumed: two sword damages need two insured swords.
185	const sumDamagePayouts = (damages: Damage[], policyItems: Item[]): number => {
186	  const unclaimed = [...policyItems];
187	
188	  return damages.reduce((sum, damage) => {
189	    if (damage.amount < 0) {
190	      throw new Error(`Damage amount cannot be negative: ${damage.amount}`);
191	    }
192	    const index = unclaimed.findIndex(({ type }) => type === damage.itemType);
193	    if (index === -1) {
194	      throw new Error(
195	        `Damaged item is not covered by the policy: ${damage.itemType}`,
196	      );
197	    }
198	    const [damagedItem] = unclaimed.splice(index, 1);
199	
200	    return sum + payoutForDamage(damage, damagedItem);
201	  }, 0);
202	};
203	
204	// The cap is twice the policy's insurance sum, i.e. what the office will pay
205	// out over the policy's whole life. Premium modifiers do not move it.
206	const policyCap = (policyItems: Item[]): number =>
207	  policyInsuranceSum(policyItems) * CAP_MULTIPLIER;
208	
209	const claim = (
210	  incident: ClaimStep["incident"],
211	  policyItems: Item[],
212	): StepResult => {
213	  const payout = sumDamagePayouts(incident.damages, policyItems);
214	
215	  return { payout, remainingCap: policyCap(policyItems) - payout };
216	};
217	
218	// Policies the office has written so far, keyed by the step index of the quote
219	// that created them — that index is how a later claim step refers to a policy.
220	// The number of entries is also exactly the number of preceding quotes, which
221	// is what decides the follow-up contract discount; deriving it here keeps the
222	// two facts from drifting apart.
223	type PoliciesSoFar = Map<number, Item[]>;
224	
225	export const runScenario = (scenario: Scenario): ScenarioResult => {
226	  const policies: PoliciesSoFar = new Map();
227	
228	  const results = scenario.steps.map((step, stepIndex) => {
229	    if (step.op === "claim") {
230	      return claim(step.incident, policies.get(step.policy)!);
231	    }
232	
233	    const result = quote(step.items, {
234	      customer: scenario.customer,
235	      precedingQuoteCount: policies.size,
236	    });
237	    policies.set(stepIndex, step.items);
238	
239	    return result;
240	  });
241	
242	  return { results };
243	};
